function rate(metric, value) {
  const t = {
    lcp: [2.5, 4],
    inp: [200, 500],
    cls: [0.1, 0.25],
  }[metric];
  if (value <= t[0]) return 'good';
  if (value <= t[1]) return 'needs-improvement';
  return 'poor';
}
print(rate('lcp', 2.5));
print(rate('inp', 420));
print(rate('cls', 0.32));

